"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["73500"],{68570(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.formulario_portavel.obrigatoriedade_invalida","status":422,"titulo":"A obrigatoriedade \xe9 SEMPRE ou NUNCA sem predicado, ou QUANDO com ele"},"descricao":{"codigo":"uniplus.formulario_portavel.obrigatoriedade_invalida","requisitos":[],"oQueAconteceu":["A avalia\xe7\xe3o de um formul\xe1rio sem cadastro confere as regras de um formul\xe1rio apresentado contra respostas simuladas, sem gravar nada nem registrar o conte\xfado enviado. A obrigatoriedade de um campo, de um grupo ou de um termo nas regras recebidas n\xe3o \xe9 coerente: o valor n\xe3o \xe9 `SEMPRE`, `NUNCA` nem `QUANDO` (inclusive o texto vazio), ou `SEMPRE` e `NUNCA` v\xeam com o predicado `regras.obrigatoriedade.predicado`, ou `QUANDO` vem sem ele. A mensagem \xe9 \\"A obrigatoriedade \xe9 SEMPRE ou NUNCA sem predicado, ou QUANDO com ele.\\", e o `field` \xe9 o caminho do elemento seguido de `regras.obrigatoriedade`, como `paginas[0].itens[2].regras.obrigatoriedade`. Quando a condi\xe7\xe3o da obrigatoriedade (`regras.obrigatoriedade.predicado`) \xe9 recusada, todas as recusas dela voltam, cada uma com o caminho completo, como `paginas[0].itens[2].regras.obrigatoriedade.predicado[0][1].operador`, e a forma da obrigatoriedade deixa de ser conferida.","A recusa vem na lista `errors` da resposta, uma entrada por recusa, cada uma com `field` igual ao caminho do elemento recusado nas regras enviadas, por exemplo `paginas[0].itens[2]`, ou mais fundo quando a recusa \xe9 de uma parte dele. As regras recebidas s\xe3o lidas por inteiro antes da avalia\xe7\xe3o, nesta ordem: as p\xe1ginas (com os itens e os grupos de cada uma), os termos, as deriva\xe7\xf5es, os resumos de grupo e, por fim, o conjunto, e todas as recusas de uma mesma etapa voltam juntas. A confer\xeancia do conjunto (c\xf3digo repetido, refer\xeancia a algo que o formul\xe1rio n\xe3o tem) s\xf3 vem depois que nenhum elemento foi recusado, e \xe9 a \xfanica recusa sem `field`. Havendo defeito de estrutura do documento (elemento nulo numa lista ou grupo sem `ocorrencias`), s\xf3 as recusas de estrutura voltam, cada uma no caminho do elemento, e nada mais \xe9 lido.","As propriedades de texto que o corpo n\xe3o pode omitir, como o c\xf3digo, a obrigatoriedade e a opera\xe7\xe3o, ausentes ou nulas, s\xe3o recusadas antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo."],"comoResolver":["Use `SEMPRE` ou `NUNCA` sem `regras.obrigatoriedade.predicado`, ou `QUANDO` com ele preenchido, e repita a avalia\xe7\xe3o."],"ondeAparece":["Avalia\xe7\xe3o de formul\xe1rio sem cadastro"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Formulario portavel"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);